begin;
alter table public.orders add column if not exists manual_payment_status text,add column if not exists manual_confirmed_at timestamptz,add column if not exists manual_confirmed_by uuid references auth.users(id) on delete restrict;
update public.orders set manual_payment_status='awaiting_manual_confirmation' where payment_purpose='business_setup'and payment_method='manual-bank'and order_status<>'paid'and manual_payment_status is null;
alter table public.orders add constraint orders_manual_payment_state_check check(payment_purpose is distinct from'business_setup'or payment_method<>'manual-bank'or(order_status='paid'and manual_payment_status is null)or(manual_payment_status in('awaiting_manual_confirmation','confirmed','rejected')and(manual_payment_status<>'confirmed'or(order_status='paid'and paid_at is not null and manual_confirmed_at is not null and manual_confirmed_by is not null))));
create table public.manual_payment_confirmations(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id)on delete restrict,confirmed_by uuid not null references auth.users(id)on delete restrict,amount_minor bigint not null check(amount_minor>0),currency text not null check(currency='NGN'),payment_reference text not null check(length(payment_reference)between 6 and 120),confirmed_at timestamptz not null default now(),audit_note text check(audit_note is null or length(audit_note)<=500),unique(order_id),unique(payment_reference));
alter table public.manual_payment_confirmations enable row level security;
create policy manual_payment_confirmations_admin_read on public.manual_payment_confirmations for select to authenticated using(public.is_admin());
grant select on public.manual_payment_confirmations to authenticated;revoke insert,update,delete on public.manual_payment_confirmations from public,anon,authenticated;
create or replace function public.confirm_manual_business_setup_payment(p_order_id uuid,p_admin_user_id uuid,p_amount_minor bigint,p_payment_reference text,p_audit_note text default null)returns uuid language plpgsql security definer set search_path=''as $$declare v_order public.orders;v_role text;v_existing public.manual_payment_confirmations;begin if auth.role()<>'service_role'then raise exception'forbidden';end if;select role into v_role from public.profiles where user_id=p_admin_user_id;if v_role is distinct from'admin'then raise exception'admin_required';end if;select*into v_order from public.orders where id=p_order_id for update;if not found or v_order.payment_purpose<>'business_setup'or v_order.payment_method<>'manual-bank'then raise exception'invalid_manual_order';end if;select*into v_existing from public.manual_payment_confirmations where order_id=p_order_id;if found then if v_existing.amount_minor<>p_amount_minor or v_existing.currency<>v_order.currency or v_existing.payment_reference<>p_payment_reference then raise exception'confirmation_conflict';end if;return p_order_id;end if;if v_order.order_status<>'pending_payment'or v_order.manual_payment_status<>'awaiting_manual_confirmation'then raise exception'ineligible_manual_order';end if;if p_amount_minor<>v_order.amount_minor or v_order.currency<>'NGN'then raise exception'payment_validation_failed';end if;insert into public.manual_payment_confirmations(order_id,confirmed_by,amount_minor,currency,payment_reference,audit_note)values(p_order_id,p_admin_user_id,p_amount_minor,'NGN',p_payment_reference,nullif(trim(p_audit_note),''));update public.orders set status='payment-verified',verified_at=coalesce(verified_at,now()),order_status='paid',onboarding_status='awaiting_client_information',paid_at=coalesce(paid_at,now()),manual_payment_status='confirmed',manual_confirmed_at=coalesce(manual_confirmed_at,now()),manual_confirmed_by=p_admin_user_id,fulfillment_count=fulfillment_count+1,updated_at=now()where id=p_order_id;return p_order_id;end$$;
revoke all on function public.confirm_manual_business_setup_payment(uuid,uuid,bigint,text,text)from public,anon,authenticated;grant execute on function public.confirm_manual_business_setup_payment(uuid,uuid,bigint,text,text)to service_role;
commit;
